        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, count(*) n, quantile_cont(c.duration,0.95)/1e6 p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-admin-user-service' AND p.span_name='AdminUserController.getAllUsers' GROUP BY ALL", "claim": "Inside the slow getAllUsers spans only a fast outgoing GET (about 9 ms) child exists, so the time is in the method itself."},
